typedef struct { int channel; void* buf; int len; int status; } dma_desc_t;

void dma_map_buffer(dma_desc_t* d) { (void)d; }
void dma_submit(dma_desc_t* d) { (void)d; }
void dma_unmap_buffer(dma_desc_t* d) { (void)d; }
void dma_release_channel(dma_desc_t* d) { (void)d; }

void dma_map_submit_release(dma_desc_t* desc)
{
  dma_map_buffer(desc);
  dma_submit(desc);
  dma_unmap_buffer(desc);
  dma_release_channel(desc);
}

int dma_get_channel_status(dma_desc_t* desc)
{
  return desc->status;
}
